 "content": "def transform(grid):
    """Convert the colored 3x3 tokens into a connected path, starting at 5."""
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]

    # The 5 marker is in the right-hand 7-column output panel (input cols 8..14).
    marker = next(( (r, c - 8)
                    for r, row in enumerate(grid)
                    for c, value in enumerate(row)
                    if value == 5 and c >= 8), None)
    if marker is None:
        return out
    mr, col = marker
    out[mr][col] = 5
    row = mr + 1

    # Each color is a directed run: (direction, length).
    # Right = +1, left = -1, down = +1 row.
    rules = {1: ("right", 3), 2: ("left", 2), 3: ("left", 4), 6: ("down", 2)}

    # Read each panel top-to-bottom, left panel first, then right panel.
    starts = [r for r in range(0, h - 2, 4)]
    for x0 in (0, 4):
        for y0 in starts:
            color = next((grid[y][x] for y in range(y0, min(y0 + 3, h))
                          for x in range(x0, x0 + 3) if grid[y][x] not in (0, 4, 5)), None)
            if color not in rules:
                continue
            direction, length = rules[color]
            if direction == "down":
                for _ in range(length):
                    if row < h and 0 <= col < 7:
                        out[row][col] = color
                    row += 1
            else:
                step = 1 if direction == "right" else -1
                for i in range(length):
                    x = col + step * i
                    if row < h and 0 <= x < 7:
                        out[row][x] = color
                col += step * (length - 1)
                row += 1
    return out
